```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    static constexpr int BASE = 1000000000;
    vector<int> limbs;

public:
    string abbreviateProduct(int left, int right) {
        limbs.clear();
        limbs.reserve(4000);
        limbs.push_back(1);

        for (int i = left; i <= right; ++i) {
            multiply(i);
        }

        int C = 0;
        while (!limbs.empty() && limbs[0] % 10 == 0) {
            divide10();
            ++C;
        }

        string s = toString();
        if (s.length() > 10) {
            return s.substr(0, 5) + "..." + s.substr(s.length() - 5) + "e" + to_string(C);
        }
        return s + "e" + to_string(C);
    }

private:
    void multiply(int n) {
        long long carry = 0;
        for (int i = 0; i < (int)limbs.size(); ++i) {
            long long cur = (long long)limbs[i] * n + carry;
            limbs[i] = (int)(cur % BASE);
            carry = cur / BASE;
        }
        while (carry > 0) {
            limbs.push_back((int)(carry % BASE));
            carry /= BASE;
        }
    }

    void divide10() {
        long long rem = 0;
        for (int i = (int)limbs.size() - 1; i >= 0; --i) {
            long long cur = rem * BASE + limbs[i];
            limbs[i] = (int)(cur / 10);
            rem = cur % 10;
        }
        while (!limbs.empty() && limbs.back() == 0) {
            limbs.pop_back();
        }
    }

    string toString() {
        if (limbs.empty()) return "0";
        string res = to_string(limbs.back());
        for (int i = (int)limbs.size() - 2; i >= 0; --i) {
            string part = to_string(limbs[i]);
            res += string(9 - part.length(), '0') + part;
        }
        return res;
    }
};
```

