#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size();
        int n = grid[0].size();
        int total = m * n;
        int top = total;
        vector<vector<int>> original = grid;

        for (auto &h : hits) {
            grid[h[0]][h[1]] = 0;
        }

        vector<int> parent(total + 1);
        vector<int> sz(total + 1, 0);
        for (int i = 0; i <= total; ++i) parent[i] = i;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (grid[i][j] == 1) sz[i * n + j] = 1;

        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (sz[ra] < sz[rb]) {
                int t = ra; ra = rb; rb = t;
            }
            parent[rb] = ra;
            sz[ra] += sz[rb];
        };

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0) continue;
                int id = i * n + j;
                if (i == 0) unite(id, top);
                if (i + 1 < m && grid[i + 1][j] == 1) unite(id, (i + 1) * n + j);
                if (j + 1 < n && grid[i][j + 1] == 1) unite(id, i * n + j + 1);
            }
        }

        vector<int> ans(hits.size(), 0);
        int dx[4] = {-1, 1, 0, 0};
        int dy[4] = {0, 0, -1, 1};

        for (int i = (int)hits.size() - 1; i >= 0; --i) {
            int x = hits[i][0];
            int y = hits[i][1];
            if (original[x][y] == 0) {
                ans[i] = 0;
                continue;
            }
            int id = x * n + y;
            int before = sz[find(top)];
            grid[x][y] = 1;
            sz[id] = 1;
            parent[id] = id;
            if (x == 0) unite(id, top);
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                    unite(id, nx * n + ny);
                }
            }
            int after = sz[find(top)];
            ans[i] = after - before - 1;
            if (ans[i] < 0) ans[i] = 0;
        }
        return ans;
    }
};
