class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> outdeg(n, 0);
        vector<vector<int>> rev(n);

        for (int u = 0; u < n; ++u) {
            outdeg[u] = graph[u].size();
            for (int v : graph[u]) {
                rev[v].push_back(u);
            }
        }

        queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (outdeg[i] == 0) {
                q.push(i);
            }
