            q.pop();

            for (int v : rev[u]) {
                if (--outdeg[v] == 0) {
                    q.push(v);
                }
            }
        }

        vector<int> ans;
        for (int i = 0; i < n; ++i) {
            if (outdeg[i] == 0) {
                ans.push_back(i);
            }
        }

        return ans;
    }
};
