#include <bits/stdc++.h>
using namespace std;

class MKAverage {
private:
    int m, k;
    static const int MAXV = 100000;
    vector<int> bitCnt;
    vector<long long> bitSum;
    queue<int> q;
    long long totalSum;
    int bitMask;

    void update(int idx, int dc, long long ds) {
        for (; idx <= MAXV; idx += idx & -idx) {
            bitCnt[idx] += dc;
            bitSum[idx] += ds;
        }
    }

    long long sumSmallest(int t) {
        if (t <= 0) return 0;
        int idx = 0;
        long long curCnt = 0, curSum = 0;
        for (int step = bitMask; step > 0; step >>= 1) {
            int next = idx + step;
            if (next <= MAXV && curCnt + bitCnt[next] < t) {
                idx = next;
                curCnt += bitCnt[next];
                curSum += bitSum[next];
            }
        }
        int val = idx + 1;
        curSum += (long long)(t - curCnt) * val;
        return curSum;
    }

public:
    MKAverage(int m, int k) : m(m), k(k), bitCnt(MAXV + 1, 0), bitSum(MAXV + 1, 0), totalSum(0) {
        bitMask = 1;
        while (bitMask <= MAXV) bitMask <<= 1;
        bitMask >>= 1;
    }

    void addElement(int num) {
        if ((int)q.size() == m) {
            int old = q.front();
            q.pop();
            update(old, -1, -old);
            totalSum -= old;
        }
        q.push(num);
        update(num, 1, num);
        totalSum += num;
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        long long smallK = sumSmallest(k);
        long long smallMK = sumSmallest(m - k);
        long long middleSum = smallMK - smallK;
        return (int)(middleSum / (m - 2 * k));
    }
};
