class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        unordered_map<int, int> posToIndex;
        for (int i = 0; i < n; ++i) {
            posToIndex[stones[i]] = i;
        }

        vector<unordered_set<int>> dp(n);
        dp[0].insert(0);

        for (int i = 0; i < n; ++i) {
            for (int k : dp[i]) {
                for (int jump = k - 1; jump <= k + 1; ++jump) {
                    if (jump <= 0) continue;

                    int nextPos = stones[i] + jump;
                    auto it = posToIndex.find(nextPos);
                    if (it != posToIndex.end()) {
                        dp[it->second].insert(jump);
                    }
                }
            }
        }

        return !dp[n - 1].empty();
    }
};
```

