#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        unordered_map<int, int> cnt;
        unordered_map<int, int> freqCnt;
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = nums[i];
            int old = cnt[x];
            if (old > 0) {
                freqCnt[old]--;
                if (freqCnt[old] == 0) freqCnt.erase(old);
            }
            cnt[x] = old + 1;
            freqCnt[old + 1]++;

            int distinct = cnt.size();
            bool ok = false;
            if (freqCnt.size() == 1) {
                int f = freqCnt.begin()->first;
                if (f == 1 || distinct == 1) ok = true;
            } else if (freqCnt.size() == 2) {
                auto it = freqCnt.begin();
                int f1 = it->first, c1 = it->second;
                ++it;
                int f2 = it->first, c2 = it->second;
                if (f1 > f2) {
                    swap(f1, f2);
                    swap(c1, c2);
                }
                if (f2 == f1 + 1 && c2 == 1) ok = true;
                if (f1 == 1 && c1 == 1) ok = true;
            }
            if (ok) ans = i + 1;
        }
        return ans;
    }
};
