class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        vector<int> pos(n), amount(n);
        for (int i = 0; i < n; ++i) {
            pos[i] = fruits[i][0];
            amount[i] = fruits[i][1];
        }

        auto steps = [&](int l, int r) -> long long {
            long long a = pos[l], b = pos[r], s = startPos;
            if (b <= s) return s - a;
            if (a >= s) return b - s;
            return (b - a) + min(s - a, b - s);
        };

        long long sum = 0, ans = 0;
        int l = 0;

        for (int r = 0; r < n; ++r) {
            sum += amount[r];

            while (l <= r && steps(l, r) > k) {
                sum -= amount[l];
                ++l;
            }

            if (l <= r) {
                ans = max(ans, sum);
            }
        }

        return (int)ans;
    }
};
