            int sum1 = prefix[i + firstLen] - prefix[i];
            for (int j = 0; j + secondLen <= n; j++) {
                if (i + firstLen <= j || j + secondLen <= i) {
                    int sum2 = prefix[j + secondLen] - prefix[j];
                    ans = max(ans, sum1 + sum2);
                }
            }
        }

        return ans;
    }
};
