using namespace std;

class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        vector<long long> v(n);
        for (int i = 0; i < n; ++i) {
            v[i] = min(flowers[i], target);
        }
        sort(v.begin(), v.end());

        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + v[i];
        }

        int base = 0;
        for (int i = 0; i < n; ++i) {
            if (v[i] == target) ++base;
        }

        long long ans = 0;
        long long cost = 0;
        int k = base;

        while (true) {
            if (cost <= newFlowers) {
                long long rem = newFlowers - cost;
                int m = n - k;
                long long bestMin = 0;

                if (m > 0) {
                    int lo = 0, hi = target - 1;
                    while (lo <= hi) {
                        int mid = lo + (hi - lo) / 2;
                        int idx = lower_bound(v.begin(), v.begin() + m, mid) - v.begin();
                        long long need = 1LL * idx * mid - pref[idx];
                        if (need <= rem) {
                            bestMin = mid;
                            lo = mid + 1;
                        } else {
                            hi = mid - 1;
                        }
                    }
                }

                ans = max(ans, 1LL * k * full + bestMin * partial);
            } else {
                break;
            }

            if (k == n) break;
            int idxNew = n - k - 1;
            cost += target - v[idxNew];
            ++k;
        }

        return ans;
    }
};
