class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        int bestNode = -1;
        int bestCount = n + 1;
        for (int remove : initial) {
            vector<char> infected(n, 0);
            queue<int> q;
            for (int src : initial) {
                if (src == remove) continue;
                if (!infected[src]) {
                    infected[src] = 1;
                    q.push(src);
                }
            }
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v = 0; v < n; ++v) {
                    if (v == remove) continue;
                    if (graph[u][v] && !infected[v]) {
                        infected[v] = 1;
                        q.push(v);
                    }
                }
            }
            int cnt = 0;
            for (int i = 0; i < n; ++i) if (infected[i]) ++cnt;
            if (cnt < bestCount || (cnt == bestCount && (bestNode == -1 || remove < bestNode))) {
                bestCount = cnt;
                bestNode = remove;
            }
        }
        return bestNode;
    }
};

