class Solution {
public:
    int minAreaRect(vector<vector<int>>& points) {
        map<int, vector<int>> cols;
        for (const auto& p : points) {
            cols[p[0]].push_back(p[1]);
        }

        for (auto& [x, ys] : cols) {
            sort(ys.begin(), ys.end());
        }

        int ans = INT_MAX;
        vector<int> xs;
        for (const auto& [x, ys] : cols) {
            xs.push_back(x);
        }

        for (int i = 0; i < (int)xs.size(); ++i) {
            for (int j = i + 1; j < (int)xs.size(); ++j) {
                int x1 = xs[i];
                int x2 = xs[j];
                const auto& ys1 = cols[x1];
                const auto& ys2 = cols[x2];

                int p = 0, q = 0;
