class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        int n = bloomDay.size();
        if ((long long)m * k > n) return -1;

        auto canMake = [&](int day) {
            int bouquets = 0, flowers = 0;
            for (int x : bloomDay) {
                if (x <= day) {
                    flowers++;
                    if (flowers == k) {
                        bouquets++;
                        flowers = 0;
                    }
                } else {
                    flowers = 0;
                }
            }
            return bouquets >= m;
        };

        int lo = 1, hi = 1e9;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (canMake(mid)) hi = mid;
            else lo = mid + 1;
        }

        return lo;
    }
};
