class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int total = 1 << n;
        const int INF = 1e9;
        vector<int> sessions(total, INF);
        vector<int> rem(total, -1);

        sessions[0] = 1;
        rem[0] = sessionTime;

        for (int mask = 0; mask < total; ++mask) {
            if (sessions[mask] == INF) continue;

            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;

                int nmask = mask | (1 << i);
                int ns = sessions[mask];
                int nr;

                if (tasks[i] <= rem[mask]) {
                    nr = rem[mask] - tasks[i];
                } else {
                    ns += 1;
                    nr = sessionTime - tasks[i];
                }

                if (ns < sessions[nmask] ||
                    (ns == sessions[nmask] && nr > rem[nmask])) {
                    sessions[nmask] = ns;
                    rem[nmask] = nr;
                }
            }
        }

        return sessions[total - 1];
    }
};
