```cpp
class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int n = nums.size();
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        int full = 1 << n;
        vector<int> sum(full, 0);
        vector<char> dp(full, 0);
        dp[0] = 1;
        for (int mask = 0; mask < full; ++mask) {
            if (!dp[mask]) continue;
            int rem = sum[mask] % target;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (rem + nums[i] <= target) {
                    int nmask = mask | (1 << i);
                    dp[nmask] = 1;
                    sum[nmask] = sum[mask] + nums[i];
                }
            }
        }
        return dp[full - 1];
    }
};
```

