class Solution {
public:
    int maxSizeSlices(vector<int>& slices) {
        int n = slices.size() / 3;
        vector<int> a(slices.begin(), slices.end() - 1);
        vector<int> b(slices.begin() + 1, slices.end());
        return max(helper(a, n), helper(b, n));
    }

private:
    int helper(vector<int>& arr, int k) {
        int m = arr.size();
        const int NEG = -1e9;
        vector<vector<int>> dp(m + 1, vector<int>(k + 1, NEG));
        dp[0][0] = 0;

        for (int i = 1; i <= m; i++) {
            dp[i][0] = 0;
            for (int j = 1; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];

                int prev = NEG;
                if (i >= 2) prev = dp[i - 2][j - 1];
                else if (j == 1) prev = 0;

                if (prev != NEG) {
                    dp[i][j] = max(dp[i][j], prev + arr[i - 1]);
                }
            }
        }

        return dp[m][k];
    }
};
