class Solution {
public:
    vector<int> parent;
    vector<int> rank;

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;

        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
    }

    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        parent.resize(n);
        rank.assign(n, 0);

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        vector<bool> result;

        for (const auto& req : requests) {
            int u = req[0];
            int v = req[1];

            int ru = find(u);
            int rv = find(v);

            if (ru == rv) {
                result.push_back(true);
                continue;
            }

            bool valid = true;

            for (const auto& res : restrictions) {
                int a = res[0];
                int b = res[1];

                int ra = find(a);
                int rb = find(b);

                if ((ra == ru && rb == rv) || (ra == rv && rb == ru)) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                unite(u, v);
                result.push_back(true);
            } else {
                result.push_back(false);
            }
        }

        return result;
    }
};
