        int curr = graph[start][0];

        while (true) {
            result.push_back(curr);

            if (graph[curr].size() == 1) {
                break;
            }

            int prev = result[result.size() - 2];
            int next = (graph[curr][0] == prev) ? graph[curr][1] : graph[curr][0];
            curr = next;
        }

        return result;
    }
};
