```cpp
#include <vector>
#include <set>
using namespace std;

class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> low, high;

        auto balance = [&]() {
            while (low.size() > high.size() + 1) {
                auto it = prev(low.end());
                high.insert(*it);
                low.erase(it);
            }
            while (low.size() < high.size()) {
                auto it = high.begin();
                low.insert(*it);
                high.erase(it);
            }
        };

        auto add = [&](int x) {
            if (low.empty() || x <= *low.rbegin()) {
                low.insert(x);
            } else {
                high.insert(x);
            }
            balance();
        };

        auto remove = [&](int x) {
            if (!low.empty() && x <= *low.rbegin()) {
                auto it = low.find(x);
                if (it != low.end()) low.erase(it);
                else high.erase(high.find(x));
            } else {
                auto it = high.find(x);
                high.erase(it);
            }
            balance();
        };

        auto getMedian = [&]() -> double {
            if (k % 2 == 1) {
                return (double)*low.rbegin();
            } else {
                return ((double)*low.rbegin() + (double)*high.begin()) / 2.0;
            }
        };

        vector<double> ans;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            add(nums[i]);
            if (i >= k) {
                remove(nums[i - k]);
            }
            if (i >= k - 1) {
                ans.push_back(getMedian());
            }
        }
        return ans;
    }
};
```

