class Solution {
public:
    char slowestKey(vector<int>& releaseTimes, string keysPressed) {
        int maxDuration = -1;
        char answer = keysPressed[0];

        for (int i = 0; i < (int)keysPressed.size(); ++i) {
            int duration = (i == 0) ? releaseTimes[0] : releaseTimes[i] - releaseTimes[i - 1];

            if (duration > maxDuration ||
                (duration == maxDuration && keysPressed[i] > answer)) {
                maxDuration = duration;
                answer = keysPressed[i];
            }
        }

        return answer;
    }
};
