class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int full = (1 << m) - 1;
        int n = stickers.size();

        vector<array<int, 26>> cnt(n);
        for (int i = 0; i < n; ++i) {
            cnt[i].fill(0);
            for (char c : stickers[i]) {
                cnt[i][c - 'a']++;
            }
        }

        vector<int> dist(1 << m, -1);
        queue<int> q;
        dist[0] = 0;
        q.push(0);

        while (!q.empty()) {
            int mask = q.front();
            q.pop();

            if (mask == full) return dist[mask];

            int pos = 0;
            while (pos < m && (mask & (1 << pos))) ++pos;
            if (pos == m) return dist[mask];

            int need = target[pos] - 'a';

            for (int s = 0; s < n; ++s) {
                if (cnt[s][need] == 0) continue;

                int nmask = mask;
                array<int, 26> avail = cnt[s];

                for (int j = 0; j < m; ++j) {
