                int na = lessA + 1;
                int nb = lessB + 1;
                auto [e, l] = dfs(m, na, nb);
                bestE = min(bestE, 1 + e);
                bestL = max(bestL, 1 + l);
            }

            memoE[n][a][b] = bestE;
            memoL[n][a][b] = bestL;
            return {bestE, bestL};
        };

