Let's write code:

```
class Solution {
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int memoE[30][30][30];
        int memoL[30][30][30];
        memset(memoE, -1, sizeof(memoE));
        memset(memoL, -1, sizeof(memoL));
        function<pair<int,int>(int,int,int)> dfs = [&](int n, int a, int b) -> pair<int,int> {
            if (a + b == n + 1) return {1,1};
            if (memoE[n][a][b] != -1) return {memoE[n][a][b], memoL[n][a][b]};
            int m = (n + 1) / 2;
            int k = 0;
            // count free pairs
            for (int i = 1; i <= n/2; ++i) {
                int L = i, R = n + 1 - i;
                if ((L == a || R == a) || (L == b || R == b)) {
                    // forced, no free bit
                } else {
                    ++k;
                }
            }
            int bestE = INT_MAX, bestL = INT_MIN;
            int totalMasks = 1 << k;
            for (int mask = 0; mask < totalMasks; ++mask) {
                vector<int> winners;
                int bit = 0;
                for (int i = 1; i <= n/2; ++i) {
                    int L = i, R = n + 1 - i;
                    if (L == a || R == a) {
                        winners.push_back(a);
                    } else if (L == b || R == b) {
                        winners.push_back(b);
                    } else {
                        if (mask & (1 << bit)) winners.push_back(R);
                        else winners.push_back(L);
                        ++bit;
                    }
                }
                if (n % 2 == 1) {
                    winners.push_back(n/2 + 1);
                }
                sort(winners.begin(), winners.end());
                int na = -1, nb = -1;
                for (int idx = 0; idx < (int)winners.size(); ++idx) {
                    if (winners[idx] == a) na = idx + 1;
                    if (winners[idx] == b) nb = idx + 1;
                }
                // If na+nb == m+1, they meet next round; dfs returns 1.
                auto [e, l] = dfs(m, na, nb);
                bestE = min(bestE, 1 + e);
                bestL = max(bestL, 1 + l);
            }
            memoE[n][a][b] = bestE;
            memoL[n][a][b] = bestL;
            return {bestE, bestL};
        };
        auto res = dfs(n, firstPlayer, secondPlayer);
        return {res.first, res.second};
    }
};
```

