#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int memoE[30][30][30];
        int memoL[30][30][30];
        memset(memoE, -1, sizeof(memoE));
        memset(memoL, -1, sizeof(memoL));

        function<pair<int,int>(int,int,int)> dfs = [&](int n, int a, int b) -> pair<int,int> {
            if (a + b == n + 1) return {1, 1};
            if (memoE[n][a][b] != -1) return {memoE[n][a][b], memoL[n][a][b]};

            int m = (n + 1) / 2;
            int k = 0;
            for (int i = 1; i <= n / 2; ++i) {
                int L = i, R = n + 1 - i;
                if ((L == a || R == a) || (L == b || R == b)) {
                    // forced
                } else {
                    ++k;
                }
            }

            int bestE = INT_MAX, bestL = INT_MIN;
            int totalMasks = 1 << k;
            for (int mask = 0; mask < totalMasks; ++mask) {
                int lessA = 0, lessB = 0;
                int bit = 0;
                for (int i = 1; i <= n / 2; ++i) {
                    int L = i, R = n + 1 - i;
                    int w;
                    if (L == a || R == a) {
                        w = a;
                    } else if (L == b || R == b) {
                        w = b;
                    } else {
                        if (mask & (1 << bit)) w = R;
                        else w = L;
                        ++bit;
                    }
                    if (w < a) ++lessA;
                    if (w < b) ++lessB;
                }
                if (n % 2 == 1) {
                    int mid = n / 2 + 1;
                    if (mid < a) ++lessA;
                    if (mid < b) ++lessB;
                }
                int na = lessA + 1;
                int nb = lessB + 1;
                auto [e, l] = dfs(m, na, nb);
                bestE = min(bestE, 1 + e);
                bestL = max(bestL, 1 + l);
            }

            memoE[n][a][b] = bestE;
            memoL[n][a][b] = bestL;
            return {bestE, bestL};
        };

        auto res = dfs(n, firstPlayer, secondPlayer);
        return {res.first, res.second};
    }
};
