#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto &e : edges) {
            int u = e[0], v = e[1];
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        bool coprime[51][51] = {};
        for (int i = 1; i <= 50; ++i) {
            for (int j = 1; j <= 50; ++j) {
                coprime[i][j] = (std::gcd(i, j) == 1);
            }
        }

        vector<int> ans(n, -1);
        vector<int> last(51, -1);
        vector<int> depth(n, 0);

        struct Event {
            int u, parent, prev;
            bool enter;
        };

        vector<Event> st;
        st.push_back({0, -1, -1, true});

        while (!st.empty()) {
            Event e = st.back();
            st.pop_back();

            int u = e.u;

            if (e.enter) {
                int val = nums[u];
                int best = -1;
                int bestDepth = -1;

                for (int y = 1; y <= 50; ++y) {
                    if (coprime[val][y] && last[y] != -1) {
                        int a = last[y];
                        if (depth[a] > bestDepth) {
                            bestDepth = depth[a];
                            best = a;
                        }
                    }
                }

                ans[u] = best;

                int prev = last[val];
                last[val] = u;

                st.push_back({u, e.parent, prev, false});

                for (int v : adj[u]) {
                    if (v == e.parent) continue;
                    depth[v] = depth[u] + 1;
                    st.push_back({v, u, -1, true});
                }
            } else {
                last[nums[u]] = e.prev;
            }
        }

        return ans;
    }
};
```

