#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<string> uncommonFromSentences(string s1, string s2) {
        unordered_map<string, int> freq;
        stringstream ss(s1 + " " + s2);
        string word;
        while (ss >> word) {
            freq[word]++;
        }

        vector<string> result;
        for (const auto& [w, count] : freq) {
            if (count == 1) {
                result.push_back(w);
            }
        }
        return result;
    }
};
