#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> indegree(n, 0);

        for (int i = 0; i < n; ++i) {
            if (leftChild[i] != -1) {
                indegree[leftChild[i]]++;
                if (indegree[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                indegree[rightChild[i]]++;
                if (indegree[rightChild[i]] > 1) return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }

        if (root == -1) return false;

        queue<int> q;
        vector<bool> visited(n, false);
        q.push(root);
        visited[root] = true;
        int count = 0;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            count++;

            int children[2] = { leftChild[node], rightChild[node] };
            for (int child : children) {
                if (child != -1) {
                    if (visited[child]) return false;
                    visited[child] = true;
                    q.push(child);
                }
            }
        }

        return count == n;
    }
};
```

