                        if (c == old) continue;
                        word[j] = c;
                        if (dict.count(word)) {
                            if (word == endWord) return level + 1;
                            dict.erase(word);
                            q.push(word);
                        }
                    }
                    word[j] = old;
                }
            }
            ++level;
        }
        return 0;
    }
};
